(function(root){
function createReportPDF(jsPDF,state,result){
 const doc=new jsPDF({unit:'mm',format:'a4',compress:true}),ink='#243c36',muted='#64705d',palette=['#c5d4af','#e9d5ae','#b9cfcb','#d8c6bc','#c9c8dc','#dfcba0'];
 const n=value=>Number(value.toFixed(2)).toString();
 function text(value,x,y,size=8,color=ink,bold=false,options={}){doc.setTextColor(color);doc.setFont('helvetica',bold?'bold':'normal');doc.setFontSize(size);doc.text(String(value),x,y,options);}
 function fit(value,x,y,width,size=12,bold=true){doc.setFont('helvetica',bold?'bold':'normal');doc.setFontSize(size);const lines=doc.splitTextToSize(String(value),width);text(lines[0]+(lines.length>1?'...':''),x,y,size,ink,bold);}
 function heading(sheet,index,first){const y=first?65.5:18;fit('Sheet '+(index+1)+' / '+result.sheets.length+' · '+sheet.label+' · '+n(sheet.w)+' × '+n(sheet.h)+' cm',12,y,186,12);text(sheet.pieces.length+' pieces · Saw kerf '+n(state.kerf*10)+' mm'+(sheet.isGuillotine===false?' · Free layout':''),12,y+6,8,muted);return y+(first?9:12);}
 function summary(){text(state.name||'Workshop project',12,15.5,12,ink,true);text('Y O U R   C U T T I N G   P L A N',12,18.4,7,'#7a8b74',true);text('A place for every piece.',12,26,17,ink,true);const placed=result.sheets.reduce((a,s)=>a+s.pieces.length,0);const adjusted=!!state.manualLayout;const status=adjusted?'Manually adjusted layout · '+placed+' pieces placed':'Layout ready · '+placed+' pieces placed · Best of '+(result.arrangementsEvaluated||0)+' arrangements · '+(state.rotate?'Rotation allowed':'Original orientation preserved');text(status,12,32.5,8,muted);const utilization=result.area?100*result.used/result.area:0,band=state.parts.reduce((sum,p)=>{const e=p.edges||{};return sum+((e.top?p.w:0)+(e.bottom?p.w:0)+(e.left?p.h:0)+(e.right?p.h:0))*p.qty;},0)/100;const cards=[['Material utilization',utilization.toFixed(1),'%'],['Sheets required',String(result.sheets.length),'sheets'],['Unused area',(100-utilization).toFixed(1),'%'],['Edge banding',band.toFixed(2),'m total']];cards.forEach(([label,value,unit],i)=>{const x=12+i*47;doc.setFillColor(i===0?'#edf3e5':'#f5f7f1');doc.setDrawColor('#e0e5da');doc.setLineWidth(.25);doc.roundedRect(x,36.5,45.5,16.3,2,2,'FD');text(label,x+2.2,41.5,7,muted);text(value,x+2.2,48.5,15,ink,true);doc.setFontSize(15);doc.setFont('helvetica','bold');const offset=doc.getTextWidth(value)+1.2;text(unit,x+2.2+offset,48.5,9,'#8a9580',true);});doc.setDrawColor('#cbd2c6');doc.line(12,57,198,57);}
 function diagram(sheet,y,height){const pad=Math.max(sheet.w,sheet.h)*.065,scale=Math.min(186/(sheet.w+2*pad),height/(sheet.h+2*pad)),x=105-sheet.w*scale/2,top=y+(height-sheet.h*scale)/2;const X=v=>x+v*scale,Y=v=>top+v*scale;doc.setDrawColor('#a8b29b');doc.setFillColor('#e8eadf');doc.setLineWidth(.15);doc.rect(x,top,sheet.w*scale,sheet.h*scale,'FD');
 for(const p of sheet.pieces){doc.setFillColor(palette[p.color%6]||palette[0]);doc.setDrawColor('#ffffff');doc.setLineWidth(.15);doc.rect(X(p.x),Y(p.y),p.w*scale,p.h*scale,'FD');const size=Math.min(sheet.w/65,p.w/8,p.h/3)*scale*2.83465;if(size>1.2){text(p.label.slice(0,20),X(p.x+p.w/2),Y(p.y+p.h/2)-size*.2/2.83465,size,ink,false,{align:'center'});text(n(p.w)+' × '+n(p.h)+' cm',X(p.x+p.w/2),Y(p.y+p.h/2)+3.8,10.5,muted,false,{align:'center'});}const e=p.edges||{},edges=p.turn?{top:e.left,right:e.top,bottom:e.right,left:e.bottom}:e;doc.setDrawColor('#275b45');doc.setLineWidth(.4);if(edges.top)doc.line(X(p.x),Y(p.y),X(p.x+p.w),Y(p.y));if(edges.bottom)doc.line(X(p.x),Y(p.y+p.h),X(p.x+p.w),Y(p.y+p.h));if(edges.left)doc.line(X(p.x),Y(p.y),X(p.x),Y(p.y+p.h));if(edges.right)doc.line(X(p.x+p.w),Y(p.y),X(p.x+p.w),Y(p.y+p.h));}
 const dimensionSize=10.5;text(n(sheet.w)+' cm',X(sheet.w/2),Y(-pad*.35),dimensionSize,'#8b9781',false,{align:'center'});text(n(sheet.h)+' cm',X(-pad*.25),Y(sheet.h/2),dimensionSize,'#8b9781',false,{align:'center',angle:90});
 const free=sheet.free||[];doc.setDrawColor('#a4a7a0');doc.setLineWidth(.1);for(const f of free){doc.line(X(f.x),Y(f.y),X(f.x+f.w),Y(f.y));doc.line(X(f.x),Y(f.y+f.h),X(f.x+f.w),Y(f.y+f.h));doc.line(X(f.x),Y(f.y),X(f.x),Y(f.y+f.h));}
 function measure(x1,y1,x2,y2,label,vertical){doc.setDrawColor('#d85b55');doc.setLineWidth(.1);doc.line(X(x1),Y(y1),X(x2),Y(y2));const tick=sheet.w/160;for(const [a,b]of [[x1,y1],[x2,y2]])doc.line(X(vertical?a-tick:a),Y(vertical?b:b-tick),X(vertical?a+tick:a),Y(vertical?b:b+tick));const size=10.5;text(label,X(vertical?(x1+x2)/2:x1+(x2-x1)*.3)-(vertical?1:0),Y((y1+y2)/2)+(vertical?0:-1),size,'#d85b55',false,{align:'center',...(vertical?{angle:90}:{})});}
 for(const f of free){measure(f.x,f.y+f.h*.35,f.x+f.w,f.y+f.h*.35,n(f.w),false);const xx=f.h>sheet.h*.025?f.x+f.w*.9:sheet.w+pad*.45;measure(xx,f.y,xx,f.y+f.h,n(f.h),true);}return y+height;
 }
 function table(rows,y,continuedTitle){const xs=[12,55,110.5,169.5,198],headers=['LABEL','WIDTH (cm)','HEIGHT (cm)','QTY'];const head=()=>{doc.setFillColor('#eef1e9');doc.setDrawColor('#b9c1b4');doc.setLineWidth(.2);for(let i=0;i<4;i++){doc.setFillColor('#eef1e9');doc.rect(xs[i],y,xs[i+1]-xs[i],6.5,'FD');text(headers[i],xs[i]+2,y+4.3,8,ink,true);}y+=6.5;};if(y>265){doc.addPage();fit(continuedTitle,12,18,186,12);y=25;}head();for(const row of rows){doc.setFontSize(8);doc.setFont('helvetica','normal');const cells=row.map((v,i)=>doc.splitTextToSize(String(v),xs[i+1]-xs[i]-4)),height=Math.max(6.5,...cells.map(c=>c.length*3.5+3));if(y+height>280){doc.addPage();fit(continuedTitle,12,18,186,12);y=25;head();}for(let i=0;i<4;i++){doc.setDrawColor('#b9c1b4');doc.rect(xs[i],y,xs[i+1]-xs[i],height);cells[i].forEach((line,j)=>text(line,xs[i]+2,y+4.3+j*3.5,8));}y+=height;}return y;}
 result.sheets.forEach((sheet,index)=>{if(index)doc.addPage();if(index===0)summary();const y=heading(sheet,index,index===0),bottom=diagram(sheet,y,index===0?85:105);text('Parts to cut',12,bottom+7,10,ink,true);const groups=new Map();for(const p of sheet.pieces){const key=JSON.stringify([p.label,p.w,p.h]);if(!groups.has(key))groups.set(key,{...p,count:0});groups.get(key).count++;}const end=table([...groups.values()].map(p=>[p.label,n(p.w),n(p.h),p.count]),bottom+10,'Sheet '+(index+1)+' · Parts to cut continued');if(end+6<285)text('Dimensions match the orientation shown above.',12,end+5,8,muted);});
 if(result.unplaced.length){doc.addPage();text('Unplaced parts',12,18,12,ink,true);text('These pieces are not included in the cutting layouts.',12,25,8,muted);const groups=new Map();for(const p of result.unplaced){const key=p.groupId??p.label;if(!groups.has(key))groups.set(key,{...p,count:0});groups.get(key).count++;}table([...groups.values()].map(p=>[p.label,n(p.w),n(p.h),p.count]),32,'Unplaced parts continued');}doc.setProperties({title:'Sheetwise cutting report',creator:'Sheetwise'});return doc;
}
if(typeof module!=='undefined')module.exports={createReportPDF};else root.ReportPDF={createReportPDF};
})(typeof window!=='undefined'?window:this);
